examples.code:
package agent.policy

default allow = false

allow {
  input.action == "issue_refund"
  input.amount <= 500
  not input.account.fraud_flag
}

deny_reason["amount_exceeds_limit"] {
  input.action == "issue_refund"
  input.amount > 500
}

deny_reason["account_under_fraud_review"] {
  input.account.fraud_flag == true
}
